using IptvManagement.Infrastructure; using IptvManagement.Infrastructure.Data; using IptvManagement.Web.Components; using Serilog;
var builder=WebApplication.CreateBuilder(args); builder.Host.UseSerilog((ctx,lc)=>lc.ReadFrom.Configuration(ctx.Configuration).WriteTo.Console()); builder.Services.AddRazorComponents().AddInteractiveServerComponents(); builder.Services.AddInfrastructure(builder.Configuration); builder.Services.AddAuthorization(); var app=builder.Build(); app.UseExceptionHandler("/Fehler"); app.UseHsts(); app.UseHttpsRedirection(); app.UseStaticFiles(); app.UseAntiforgery(); app.UseAuthentication(); app.UseAuthorization(); app.MapRazorComponents<App>().AddInteractiveServerRenderMode(); app.Run();
